// customers-pricing · кейс cp-11 (.qa/tests/customers-pricing/) — «שיוך מוצרים»: загрузка / ошибка / реально пусто (#966c4100).
// Только чтение: окно открывается у первой группы и закрывается Escape без отметок; любые записи в Supabase
// абортируются и считаются нарушением. Список товаров в окне — GET rest/v1/products (перехватываем только после
// загрузки страницы, чтобы не задеть саму таблицу групп).
import { test, expect, Page, Route } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const PRODUCTS = /\/rest\/v1\/products\?/;
const EMPTY = 'אין מוצרים בקטלוג עדיין.';
const ERROR = 'אירעה שגיאה בטעינת המוצרים. נסה שוב.';

async function guardWrites(page: Page) {
  const violations: string[] = [];
  await page.route(/supabase\.co\/rest\/v1\//, (route: Route) => {
    const r = route.request();
    if (['GET', 'HEAD', 'OPTIONS'].includes(r.method())) return route.fallback();
    violations.push(`${r.method()} ${r.url()}`);
    return route.abort();
  });
  return violations;
}

async function openAssignOfFirstGroup(page: Page) {
  await page.goto('/pricing/groups');
  await expect(page.getByRole('heading', { level: 1, name: 'קבוצות מוצרים' })).toBeVisible({ timeout: 20_000 });
  const actions = page.getByRole('main').getByRole('button', { name: 'פעולות' });
  await expect(actions.first()).toBeVisible({ timeout: 20_000 });
  return async () => {
    await actions.first().click();
    await page.getByRole('menuitem', { name: 'שיוך מוצרים' }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: /^שיוך מוצרים · / })).toBeVisible();
    return dlg;
  };
}

test.describe('customers-pricing — «שיוך מוצרים»: מצבי טעינה (#966c4100)', () => {
  let violations: string[] = [];
  test.beforeEach(async ({ page }) => { violations = await guardWrites(page); });
  test.afterEach(async ({ page }) => {
    await page.keyboard.press('Escape').catch(() => {});
    expect(violations, 'окно «שיוך מוצרים» не должно ничего записывать').toEqual([]);
  });

  test('בזמן טעינה — שלד (aria-busy), בלי «אין מוצרים בקטלוג עדיין.»; אחרי הטעינה — רשימת מוצרים #966c4100 @desktop @prod-safe', async ({ page }) => {
    const open = await openAssignOfFirstGroup(page);
    await page.route(PRODUCTS, async (route) => {
      await new Promise((r) => setTimeout(r, 6_000));
      await route.fallback().catch(() => {});
    });
    const dlg = await open();
    await expect(dlg.locator('[aria-busy="true"]').first()).toBeVisible({ timeout: 3_000 });
    await expect(dlg.getByText(EMPTY)).toHaveCount(0);
    await expect(dlg.getByRole('checkbox')).toHaveCount(0);
    // всё время задержки «пусто» не появляется, затем приходит список
    await expect(dlg.getByRole('checkbox').first()).toBeVisible({ timeout: 30_000 });
    await expect(dlg.getByText(EMPTY)).toHaveCount(0);
    await expect(dlg.locator('[aria-busy="true"]')).toHaveCount(0);
  });

  test('כשל טעינה — «אירעה שגיאה בטעינת המוצרים. נסה שוב.» + «נסה שוב» טוען את הרשימה #966c4100 #59d59e6f @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    const open = await openAssignOfFirstGroup(page);
    const fail = (route: Route) => route.abort();
    await page.route(PRODUCTS, fail);
    const dlg = await open();
    // приложение повторяет запрос несколько раз (~15 с) — ждём итог
    await expect(dlg.getByText(ERROR)).toBeVisible({ timeout: 40_000 });
    await expect(dlg.getByText(EMPTY)).toHaveCount(0);
    const retry = dlg.getByRole('button', { name: 'נסה שוב' });
    await expect(retry).toBeVisible();
    await page.unroute(PRODUCTS, fail);
    await retry.click();
    await expect(dlg.getByRole('checkbox').first()).toBeVisible({ timeout: 30_000 });
    await expect(dlg.getByText(ERROR)).toHaveCount(0);
  });

  test('קטלוג ריק באמת (תשובה []) — «אין מוצרים בקטלוג עדיין.» #966c4100 @desktop @prod-safe', async ({ page }) => {
    const open = await openAssignOfFirstGroup(page);
    await page.route(PRODUCTS, (route) => route.fulfill({ status: 200, contentType: 'application/json', body: '[]' }));
    const dlg = await open();
    await expect(dlg.getByText(EMPTY)).toBeVisible({ timeout: 15_000 });
    await expect(dlg.getByRole('checkbox')).toHaveCount(0);
    await expect(dlg.getByText(ERROR)).toHaveCount(0);
  });
});
